pub fn is_type_def_item(item: &Rc<Node>) -> bool {
    ((item.connective.clone() != Connective::NoConnective) && (item.transport.clone() == None))
}

pub fn is_bare_leaf_item(item: &Rc<Node>) -> bool {
    (((((item.connective.clone() == Connective::NoConnective) && (item.body.clone() == None)) && ((item.params.clone().len() as i64) == 0)) && (item.transport.clone() == None)) && ((item.children.clone().len() as i64) == 0))
}

pub fn is_type_alias_item(item: &Rc<Node>, source_index: Option<Rc<NewlineIndex>>) -> bool {
    (is_bare_leaf_item(&item) && is_type_alias_return_node(resolved_type(item.clone()), source_index))
}

pub fn is_type_decl_item(item: &Rc<Node>, source_index: Option<Rc<NewlineIndex>>) -> bool {
    ((is_bare_leaf_item(&item) && !is_type_alias_return_node(resolved_type(item.clone()), source_index)) || (((((item.params.clone().len() as i64) > 0) && (item.body.clone() == None)) && (item.transport.clone() == None)) && ((item.children.clone().len() as i64) == 0)))
}

pub fn is_function_item(item: &Rc<Node>) -> bool {
    ((item.body.clone() != None) && (item.type_annotation.clone() == None))
}

pub fn is_data_def_item(item: &Rc<Node>) -> bool {
    ((item.body.clone() != None) && (item.type_annotation.clone() != None))
}

pub fn is_service_def_item(item: &Rc<Node>) -> bool {
    ((item.transport.clone() != None) && ((item.children.clone().len() as i64) > 0))
}

pub fn is_resource_def_item(item: &Rc<Node>) -> bool {
    (((item.transport.clone() == None) && ((item.children.clone().len() as i64) > 0)) || ((((item.transport.clone() == None) && ((item.children.clone().len() as i64) == 0)) && ((item.properties.clone().len() as i64) > 0)) && (item.body.clone() == None)))
}

#[derive(Debug, Clone, Copy, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum ExprCategory {
    ExprCatLeaf,
    ExprCatCompound,
    ExprCatControlFlow,
    ExprCatBinding,
    ExprCatService,
    ExprCatNone,
}

pub fn classify_expr(texpr: Rc<Node>) -> ExprCategory {
    match (*texpr.expr_data.clone()).clone() {
    ExprData::ExprLiteral { .. } => ExprCategory::ExprCatLeaf,
    ExprData::ExprError { .. } => ExprCategory::ExprCatLeaf,
    ExprData::ExprVar { .. } => ExprCategory::ExprCatLeaf,
    ExprData::ExprFieldAccess { .. } => ExprCategory::ExprCatCompound,
    ExprData::ExprCall { .. } => ExprCategory::ExprCatCompound,
    ExprData::ExprMethodCall { .. } => ExprCategory::ExprCatCompound,
    ExprData::ExprRecordLit { .. } => ExprCategory::ExprCatCompound,
    ExprData::ExprListLit => ExprCategory::ExprCatCompound,
    ExprData::ExprBinOp { .. } => ExprCategory::ExprCatCompound,
    ExprData::ExprUnaryOp { .. } => ExprCategory::ExprCatCompound,
    ExprData::ExprLambda { .. } => ExprCategory::ExprCatCompound,
    ExprData::ExprStringInterp => ExprCategory::ExprCatCompound,
    ExprData::ExprCast => ExprCategory::ExprCatCompound,
    ExprData::ExprIndex => ExprCategory::ExprCatCompound,
    ExprData::ExprSlice => ExprCategory::ExprCatCompound,
    ExprData::ExprMatch => ExprCategory::ExprCatControlFlow,
    ExprData::ExprIf => ExprCategory::ExprCatControlFlow,
    ExprData::ExprForEach => ExprCategory::ExprCatControlFlow,
    ExprData::ExprBlock => ExprCategory::ExprCatControlFlow,
    ExprData::ExprLet => ExprCategory::ExprCatBinding,
    ExprData::ExprReturn => ExprCategory::ExprCatControlFlow,
    ExprData::NoExprData => ExprCategory::ExprCatNone,
    _ => ExprCategory::ExprCatNone,
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum FuncBodyShape {
    FuncBodyLet {
        name: String,
        value: Rc<Node>,
        rest: Option<Rc<Node>>,
    },
    FuncBodyBlock {
        stmts: Rc<Vec<Rc<Node>>>,
    },
    FuncBodyExpr {
        expr: Rc<Node>,
    },
}

pub fn classify_func_body(body: &Rc<Node>, source_index: Option<Rc<NewlineIndex>>) -> Rc<FuncBodyShape> {
    match (*body.expr_data.clone()).clone() {
    ExprData::ExprLet => {
        let n = let_binding_name_at(body.clone(), source_index);
let v = let_value(body.clone());
let rest = let_body(body.clone());
Rc::new(FuncBodyShape::FuncBodyLet {
    name: n,
    value: v,
    rest: rest,
})
},
    ExprData::ExprBlock => Rc::new(FuncBodyShape::FuncBodyBlock {
    stmts: body.children.clone(),
}),
    _ => Rc::new(FuncBodyShape::FuncBodyExpr {
    expr: body.clone(),
}),
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum TcoExprShape {
    TcoCall {
        func: String,
        args: Rc<Vec<Rc<Node>>>,
    },
    TcoIf {
        condition: Rc<Node>,
        then_branch: Rc<Node>,
        else_branch: Option<Rc<Node>>,
    },
    TcoMatch {
        scrutinee: Rc<Node>,
        arms: Rc<Vec<Rc<Node>>>,
    },
    TcoLet {
        name: String,
        value: Rc<Node>,
        body: Option<Rc<Node>>,
    },
    TcoBlock {
        stmts: Rc<Vec<Rc<Node>>>,
    },
    TcoOther {
        expr: Rc<Node>,
    },
}

pub fn classify_tco_expr(texpr: &Rc<Node>, source_index: Option<Rc<NewlineIndex>>) -> Rc<TcoExprShape> {
    match (*texpr.expr_data.clone()).clone() {
    ExprData::ExprCall { .. } => Rc::new(TcoExprShape::TcoCall {
    func: expr_call_func_at(texpr.clone(), source_index),
    args: texpr.children.clone(),
}),
    ExprData::ExprIf => {
        let c = if_condition(texpr.clone());
let t = if_then_branch(texpr.clone());
let e = if_else_branch(texpr.clone());
Rc::new(TcoExprShape::TcoIf {
    condition: c,
    then_branch: t,
    else_branch: e,
})
},
    ExprData::ExprMatch => {
        let scrut = match_scrutinee(texpr.clone());
let arm_list = match_arm_nodes(texpr.clone());
Rc::new(TcoExprShape::TcoMatch {
    scrutinee: scrut,
    arms: arm_list,
})
},
    ExprData::ExprLet => {
        let n = let_binding_name_at(texpr.clone(), source_index);
let v = let_value(texpr.clone());
let bd = let_body(texpr.clone());
Rc::new(TcoExprShape::TcoLet {
    name: n,
    value: v,
    body: bd,
})
},
    ExprData::ExprBlock => Rc::new(TcoExprShape::TcoBlock {
    stmts: texpr.children.clone(),
}),
    _ => Rc::new(TcoExprShape::TcoOther {
    expr: texpr.clone(),
}),
}
}

pub fn block_stmts_init(stmts: &Rc<Vec<Rc<Node>>>) -> Rc<Vec<Rc<Node>>> {
    if ((stmts.clone().len() as i64) <= 1) {
        Rc::new(vec![])
    } else {
        Rc::new(stmts.clone().iter().cloned().take(((stmts.clone().len() as i64) - 1) as usize).collect::<Vec<_>>())
    }
}

pub fn is_tco_eligible(name: &String, body: &Rc<Node>, registry: Rc<HashMap<String, Rc<ItemInfo>>>, source_index: &Option<Rc<NewlineIndex>>) -> bool {
    match lookup_item(registry, name.clone()) {
    Some(info) => (info.is_self_recursive.clone() && (info.has_non_tail_self_call.clone() == false)),
    None => (expr_has_self_call(&body, &name, &source_index) && (expr_has_non_tail_self_call(&body, &name, true, &source_index) == false)),
}
}

pub fn is_self_recursive(name: &String, body: Rc<Node>, registry: Rc<HashMap<String, Rc<ItemInfo>>>, source_index: Option<Rc<NewlineIndex>>) -> bool {
    match lookup_item(registry, name.clone()) {
    Some(info) => info.is_self_recursive.clone(),
    None => expr_has_self_call(&body, &name, &source_index),
}
}

pub fn tco_reassign_core(ordered_args: Rc<Vec<String>>, param_names: Rc<Vec<String>>, temp_var_prefix: String, temp_decl_prefix: String, temp_assign_op: String, stmt_terminator: String, continue_str: String, line_prefix: &String) -> Rc<Vec<String>> {
    {
        let temp_lets = Rc::new({ let mut __result = Vec::new(); for pair in Rc::new(ordered_args.iter().cloned().enumerate().map(|(i, v)| (i as i64, v)).collect::<Vec<_>>()).iter().cloned() { __result.push(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(line_prefix.clone(), temp_decl_prefix.clone()), temp_var_prefix.clone()), (pair.0.clone()).to_string()), temp_assign_op.clone()), pair.1.clone()), stmt_terminator.clone())); } __result });
let assigns = Rc::new({ let mut __result = Vec::new(); for pair in Rc::new(param_names.iter().cloned().enumerate().map(|(i, v)| (i as i64, v)).collect::<Vec<_>>()).iter().cloned() { __result.push(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(line_prefix.clone(), pair.1.clone()), " = ".to_string()), temp_var_prefix.clone()), (pair.0.clone()).to_string()), stmt_terminator.clone())); } __result });
v2_rt::concat(v2_rt::concat(temp_lets, assigns), Rc::new(vec![v2_rt::concat(line_prefix.clone(), continue_str)]))
}
}

pub fn emit_shared_tco_expr(mut frame: Rc<TcoFrame>, mut fn_name: String, mut emit_self_call_reassign: impl Fn(Rc<TcoReassignInput>) -> String + Clone, mut emit_non_self_call: impl Fn(Rc<TcoFrame>) -> String + Clone, mut emit_if: impl Fn(Rc<TcoFrame>) -> String + Clone, mut emit_match: impl Fn(Rc<TcoFrame>) -> String + Clone, mut emit_let: impl Fn(Rc<TcoFrame>) -> String + Clone, mut emit_block: impl Fn(Rc<TcoFrame>) -> String + Clone, mut emit_default_return: impl Fn(Rc<TcoFrame>) -> String + Clone) -> String {
    loop {
        let si = frame.scope.clone().type_env.clone().source_index.clone();
match (*frame.expr.clone().expr_data.clone()).clone() {
    ExprData::ExprCall { .. } => { if (expr_call_func_at(frame.expr.clone(), si).as_str() == fn_name.as_str()) {
            break emit_self_call_reassign(Rc::new(TcoReassignInput {
    args: frame.expr.clone().children.clone(),
    scope: frame.scope.clone(),
    depth: frame.depth.clone(),
}));
} else {
            break emit_non_self_call(frame.clone());
} },
    ExprData::ExprReturn => { let inner = return_value(frame.expr.clone());
{
            let __tco_0 = Rc::new(TcoFrame {
    expr: inner,
    scope: frame.scope.clone(),
    depth: frame.depth.clone(),
});
frame = __tco_0;
continue;
} },
    ExprData::ExprIf => { break emit_if(frame.clone()); },
    ExprData::ExprMatch => { break emit_match(frame.clone()); },
    ExprData::ExprLet => { break emit_let(frame.clone()); },
    ExprData::ExprBlock => { break emit_block(frame.clone()); },
    _ => { break emit_default_return(frame.clone()); },
}
}
}

pub fn shared_tco_body(inner: String, depth: i64, spec: &Rc<LanguageSpec>) -> String {
    {
        let syntax = spec.block_syntax.clone();
let tco = spec.tco.clone();
if syntax.significant_whitespace.clone() {
            v2_rt::concat(v2_rt::concat(v2_rt::concat(tco.loop_keyword.clone(), syntax.block_open.clone()), make_indent((depth + 1))), inner)
        } else {
            v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(tco.loop_keyword.clone(), syntax.block_open.clone()), make_indent((depth + 1))), inner), "\n".to_string()), syntax.block_close.clone())
        }
}
}

pub fn shared_tco_default_return(frame: &Rc<TcoFrame>, spec: Rc<LanguageSpec>, recurse_expr: impl Fn(Rc<Node>, Rc<InferScope>, i64) -> String + Clone) -> String {
    {
        let val_str = recurse_expr(frame.expr.clone(), frame.scope.clone(), frame.depth.clone());
v2_rt::concat(v2_rt::concat(spec.tco.clone().break_return.clone(), " ".to_string()), val_str)
}
}

pub fn shared_tco_non_self_call(frame: &Rc<TcoFrame>, target: RenderTarget, spec: Rc<LanguageSpec>, recurse_call: impl Fn(String, Rc<Vec<Rc<Node>>>, Rc<InferScope>, i64) -> String + Clone) -> String {
    match (*frame.expr.clone().expr_data.clone()).clone() {
    ExprData::ExprCall { .. } => {
        let f = expr_call_func_at(frame.expr.clone(), frame.scope.clone().type_env.clone().source_index.clone());
let call_str = recurse_call(f, frame.expr.clone().children.clone(), frame.scope.clone(), frame.depth.clone());
v2_rt::concat(v2_rt::concat(spec.tco.clone().break_return.clone(), " ".to_string()), call_str)
},
    _ => emit_error_expr("shared_tco_non_self_call expected ExprCall".to_string(), target),
}
}

pub fn shared_tco_if(frame: &Rc<TcoFrame>, fn_name: String, params: Rc<Vec<Rc<Node>>>, target: RenderTarget, spec: Rc<LanguageSpec>, recurse_expr: impl Fn(Rc<Node>, Rc<InferScope>, i64) -> String + Clone, recurse_tco: impl Fn(Rc<Node>, Rc<InferScope>, i64) -> String + Clone) -> String {
    {
        let syntax = spec.block_syntax.clone();
match (*frame.expr.clone().expr_data.clone()).clone() {
    ExprData::ExprIf => {
            let c = if_condition(frame.expr.clone());
let t = if_then_branch(frame.expr.clone());
let e = if_else_branch(frame.expr.clone());
let cond_str = recurse_expr(c, frame.scope.clone(), frame.depth.clone());
let then_str = recurse_tco(t, frame.scope.clone(), (frame.depth.clone() + 1));
let else_prefix = if syntax.significant_whitespace.clone() {
                make_indent(frame.depth.clone())
            } else {
                "".to_string()
            };
match e {
    Some(eb) => {
                let else_str = recurse_tco(eb.clone(), frame.scope.clone(), (frame.depth.clone() + 1));
if syntax.significant_whitespace.clone() {
                    v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat("if ".to_string(), cond_str), syntax.block_open.clone()), make_indent((frame.depth.clone() + 1))), then_str), "\n".to_string()), else_prefix), syntax.else_clause.clone()), make_indent((frame.depth.clone() + 1))), else_str)
                } else {
                    v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat("if ".to_string(), cond_str), syntax.block_open.clone()), make_indent((frame.depth.clone() + 1))), then_str), "\n".to_string()), syntax.else_clause.clone()), make_indent((frame.depth.clone() + 1))), else_str), "\n".to_string()), syntax.block_close.clone())
                }
},
    None => if syntax.significant_whitespace.clone() {
                v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat("if ".to_string(), cond_str), syntax.block_open.clone()), make_indent((frame.depth.clone() + 1))), then_str)
            } else {
                v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat("if ".to_string(), cond_str), syntax.block_open.clone()), make_indent((frame.depth.clone() + 1))), then_str), "\n".to_string()), syntax.block_close.clone())
            },
}
},
    _ => emit_error_expr("shared_tco_if expected ExprIf".to_string(), target),
}
}
}

pub fn shared_tco_let(frame: &Rc<TcoFrame>, fn_name: String, params: Rc<Vec<Rc<Node>>>, target: RenderTarget, recurse_expr: impl Fn(Rc<Node>, Rc<InferScope>, i64) -> String + Clone, recurse_tco: impl Fn(Rc<Node>, Rc<InferScope>, i64) -> String + Clone) -> String {
    match (*frame.expr.clone().expr_data.clone()).clone() {
    ExprData::ExprLet => {
        let n = let_binding_name_at(frame.expr.clone(), frame.scope.clone().type_env.clone().source_index.clone());
let v = let_value(frame.expr.clone());
let bd = let_body(frame.expr.clone());
let val_str = recurse_expr(v.clone(), frame.scope.clone(), frame.depth.clone());
let let_line = emit_let_binding(n.clone(), val_str, &target);
let next_scope = extend_scope(&frame.scope.clone(), &n, resolved_type(v.clone()), Rc::new(SubValueRelation::SubValueUnknown));
match bd {
    Some(b) => v2_rt::concat(v2_rt::concat(let_line, "\n".to_string()), recurse_tco(b.clone(), next_scope, frame.depth.clone())),
    None => let_line,
}
},
    _ => emit_error_expr("shared_tco_let expected ExprLet".to_string(), target),
}
}

pub fn shared_tco_block(frame: &Rc<TcoFrame>, fn_name: String, params: Rc<Vec<Rc<Node>>>, target: RenderTarget, spec: Rc<LanguageSpec>, emit_init_stmts: impl Fn(Rc<Vec<Rc<Node>>>, Rc<InferScope>, i64) -> Rc<BlockEmitState> + Clone, recurse_tco: impl Fn(Rc<Node>, Rc<InferScope>, i64) -> String + Clone) -> String {
    match (*frame.expr.clone().expr_data.clone()).clone() {
    ExprData::ExprBlock => {
        let ss = frame.expr.clone().children.clone();
if ((ss.clone().len() as i64) == 0) {
            spec.tco.clone().break_return.clone()
        } else {
            {
                let init_state = emit_init_stmts(ss.clone(), frame.scope.clone(), frame.depth.clone());
let last_str = match ss.clone().last().cloned() {
    Some(last_expr) => recurse_tco(last_expr.clone(), init_state.scope.clone(), frame.depth.clone()),
    None => spec.tco.clone().break_return.clone(),
};
if ((init_state.text.clone().len() as i64) == 0) {
                    last_str
                } else {
                    v2_rt::concat(v2_rt::concat(init_state.text.clone().join(&"\n".to_string()), "\n".to_string()), last_str)
                }
}
        }
},
    _ => emit_error_expr("shared_tco_block expected ExprBlock".to_string(), target),
}
}

pub fn shared_tco_reassign(ordered_args: Rc<Vec<String>>, param_names: Rc<Vec<String>>, spec: &Rc<LanguageSpec>) -> String {
    {
        let all_lines = tco_reassign_core(ordered_args, param_names, spec.tco.clone().temp_var_prefix.clone(), spec.tco.clone().temp_decl_prefix.clone(), spec.tco.clone().temp_assign_op.clone(), spec.block_syntax.clone().stmt_terminator.clone(), spec.tco.clone().continue_str.clone(), &"".to_string());
all_lines.join(&"\n".to_string())
}
}

pub fn is_tco_candidate(texpr: &Rc<Node>, func_name: &String, source_index: &Option<Rc<NewlineIndex>>) -> bool {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*texpr.expr_data.clone()).clone() {
    ExprData::ExprCall { .. } => (expr_call_func_at(texpr.clone(), source_index.clone()).as_str() == func_name.clone().as_str()),
    ExprData::ExprReturn => is_tco_candidate(&return_value(texpr.clone()), &func_name, &source_index),
    ExprData::ExprIf => {
            let then_cand = is_tco_candidate(&if_then_branch(texpr.clone()), &func_name, &source_index);
let else_cand = match if_else_branch(texpr.clone()) {
    Some(e) => is_tco_candidate(&e, &func_name, &source_index),
    None => false,
};
(then_cand || else_cand)
},
    ExprData::ExprMatch => { let mut __found = false; for arm_node in match_arm_nodes(texpr.clone()).iter().cloned() { if is_tco_candidate(&arm_body(&arm_node), &func_name, &source_index) { __found = true; break; } } __found },
    ExprData::ExprLet => match let_body(texpr.clone()) {
    Some(b) => is_tco_candidate(&b, &func_name, &source_index),
    None => false,
},
    ExprData::ExprBlock => { let mut __found = false; for s in texpr.children.clone().iter().cloned() { if is_tco_candidate(&s, &func_name, &source_index) { __found = true; break; } } __found },
    ExprData::NoExprData => { let mut __found = false; for child in texpr.children.clone().iter().cloned() { if is_tco_candidate(&child, &func_name, &source_index) { __found = true; break; } } __found },
    _ => false,
}
    })
}

pub fn emit_ident(name: String, target: RenderTarget) -> String {
    {
        let spec = language_spec(target);
let converted = match spec.naming_case.clone() {
    NamingCase::SnakeCase => to_snake(name),
    NamingCase::CamelCase => to_camel(name),
    NamingCase::PascalCase => capitalize_first(to_camel(name)),
    NamingCase::AsAuthored => name,
};
let is_reserved = { let mut __found = false; for r in spec.reserved_words.clone().keywords.clone().iter().cloned() { if (r.clone().as_str() == converted.clone().as_str()) { __found = true; break; } } __found };
if is_reserved {
            match (*spec.reserved_words.clone().strategy.clone()).clone() {
    ReservedWordStrategy::PrefixEscape { prefix: p, .. } => v2_rt::concat(p.clone(), converted.clone()),
    ReservedWordStrategy::SuffixEscape { suffix: s, .. } => v2_rt::concat(converted.clone(), s.clone()),
    ReservedWordStrategy::NoEscape => converted.clone(),
}
        } else {
            converted.clone()
        }
}
}

pub fn emit_export_ident(name: String, target: &RenderTarget) -> String {
    {
        let spec = language_spec(target.clone());
match (*spec.visibility.clone()).clone() {
    VisibilitySpec::CaseVisibility { export_case: ec, .. } => {
            let result = apply_naming_case(name, ec.clone());
let is_reserved = { let mut __found = false; for r in spec.reserved_words.clone().keywords.clone().iter().cloned() { if (r.clone().as_str() == result.clone().as_str()) { __found = true; break; } } __found };
if is_reserved {
                match (*spec.reserved_words.clone().strategy.clone()).clone() {
    ReservedWordStrategy::SuffixEscape { suffix: s, .. } => v2_rt::concat(result.clone(), s.clone()),
    ReservedWordStrategy::PrefixEscape { prefix: p, .. } => v2_rt::concat(p.clone(), result.clone()),
    ReservedWordStrategy::NoEscape => result.clone(),
}
            } else {
                result.clone()
            }
},
    VisibilitySpec::KeywordVisibility { .. } => emit_ident(name, target.clone()),
}
}
}

pub fn apply_bridge_method_overrides(name: String, overrides: Rc<Vec<Rc<EscapePair>>>) -> String {
    match Rc::new({ let mut __result = Vec::new(); for o in overrides.iter().cloned() { if (o.from.clone().as_str() == name.clone().as_str()) { __result.push(o); } } __result }).first().cloned() {
    Some(r#override) => r#override.to.clone(),
    None => name.clone(),
}
}

